class Solution {
    vector<vector<int>> adj;
    vector<int> quiet;
    vector<int> ans;
    void dfs(int x) {
        if (ans[x] != -1) return;
        ans[x] = x;
        for (int c : adj[x]) {
            dfs(c);
            if (quiet[ans[c]] < quiet[ans[x]]) {
                ans[x] = ans[c];
            }
        }
    }
public:
    vector<int> loudAndRich(vector<vector<int>>& richer, vector<int>& quiet) {
        int n = quiet.size();
        this->quiet = quiet;
        adj.assign(n, {});
        for (auto& r : richer) {
            adj[r[1]].push_back(r[0]);
        }
        ans.assign(n, -1);
        for (int i = 0; i < n; i++) {
            dfs(i);
        }
        return ans;
    }
};
